import type { Question } from '../../lib/types'
export const dr_strategies_questions: Question[] = [
  { id: 'd2-dr-001', domain: 2, topics: ['DR', 'RTO RPO', 'active-active'], type: 'single', stem: 'A company requires RTO under 1 minute and near-zero RPO for their critical payment system. Which DR strategy meets these requirements?', options: [{ id: 'A', text: 'Multi-Site Active-Active' }, { id: 'B', text: 'Warm Standby' }, { id: 'C', text: 'Pilot Light' }, { id: 'D', text: 'Backup and Restore' }], correct: ['A'], explanation: 'Active-Active has near-zero RPO (all regions process transactions simultaneously) and RTO under 1 minute (failover is just routing traffic to healthy regions). Most expensive but provides the best RTO/RPO metrics.', distractors: {
      D: 'Backup and Restore: RTO hours to days — far exceeds the 1-minute requirement.',
      C: 'Pilot Light: RTO 10-30 minutes for scale-up — does not meet the under-1-minute requirement.',
      B: 'Warm Standby: RTO 5-15 minutes for scale-up to production capacity — does not meet the under-1-minute requirement.'
    } },
  { id: 'd2-dr-002', domain: 2, topics: ['DR', 'backup restore', 'cost'], type: 'single', stem: 'A startup needs disaster recovery for a non-critical internal application. They accept RTO/RPO of several hours and have minimal budget. Which DR strategy minimizes ongoing cost?', options: [{ id: 'A', text: 'Active-Active multi-site' }, { id: 'B', text: 'Warm Standby' }, { id: 'C', text: 'Backup and Restore' }, { id: 'D', text: 'Pilot Light' }], correct: ['C'], explanation: 'Backup and Restore is the cheapest DR strategy. Data, AMIs, and CloudFormation templates are stored in S3 in another region. Recovery requires launching resources from scratch — RTO/RPO measured in hours. No standby infrastructure costs.', distractors: { A: 'Active-Active doubles running infrastructure — far exceeds budget for a non-critical application.', B: 'Warm Standby requires paying for a scaled-down running environment — more than pure backup and restore.', D: 'Pilot Light maintains core services running (especially databases) — costs more than pure backup/restore with no running resources.' } },
  { id: 'd2-dr-003', domain: 2, topics: ['DR', 'pilot light', 'definition'], type: 'single', stem: 'A company uses the Pilot Light DR strategy. Which resources are kept running in the DR region at all times?', options: [{ id: 'A', text: 'Only the most critical core components' }, { id: 'B', text: 'All production resources at 100% capacity ready for immediate traffic acceptance' }, { id: 'C', text: 'Full production replica at 25% capacity' }, { id: 'D', text: 'No resources running' }], correct: ['A'], explanation: 'Pilot Light keeps only critical core services running in the DR region — typically the database (continuously replicated). Non-critical resources are provisioned quickly using IaC during failover. Like a gas pilot light — minimal flame always burning.', distractors: {
      C: '25% capacity running for all services is Warm Standby (reduced capacity) — Pilot Light is minimal, not reduced capacity.',
      D: 'No resources running is Backup and Restore — Pilot Light keeps the critical "pilot light" services always on.',
      B: '100% capacity in both regions is Active-Active — the most expensive strategy.'
    } },
  { id: 'd2-dr-004', domain: 2, topics: ['DR', 'Route 53', 'failover routing'], type: 'single', stem: 'Production is in us-east-1 and a DR environment in eu-west-1. Route 53 should automatically redirect all traffic to eu-west-1 when us-east-1 fails health checks. What configuration achieves this?', options: [{ id: 'A', text: 'Route 53 weighted routing (100/0)' }, { id: 'B', text: 'Route 53 geolocation routing with default' }, { id: 'C', text: 'Route 53 latency routing' }, { id: 'D', text: 'Route 53 failover routing with health checks on the primary record' }], correct: ['D'], explanation: 'Route 53 failover routing + health checks: when the primary health check fails, Route 53 automatically serves the secondary record (eu-west-1). This is the canonical Route 53 active-passive DR pattern.', distractors: {
      C: 'Latency routing chooses the lowest-latency endpoint — doesn\'t implement active-passive failover based on health checks.',
      A: '100/0 weighted always sends to us-east-1 — no automatic health-check-based failover.',
      B: 'Geolocation routes by user location — not based on health checks or DR failover conditions.'
    } },
  { id: 'd2-dr-005', domain: 2, topics: ['DR', 'Aurora Global Database'], type: 'single', stem: 'A company uses Aurora Global Database. What are the approximate RTO and RPO when failing over to the secondary region?', options: [{ id: 'A', text: 'RTO: under 1 minute, RPO: zero data loss' }, { id: 'B', text: 'RTO: 30 minutes for promotion, RPO: 5 minutes' }, { id: 'C', text: 'RTO: under 1 minute, RPO: under 1 second' }, { id: 'D', text: 'RTO: 24 hours, RPO: 1 hour' }], correct: ['C'], explanation: 'Aurora Global Database uses storage-level replication with typically <1 second lag (RPO). Managed failover promotes the secondary to primary in typically under 1 minute (RTO). Meets the most aggressive DR requirements for relational databases.', distractors: {
      D: 'These figures describe Backup and Restore — Aurora Global Database provides continuous replication with sub-second lag.',
      A: 'Zero RPO is not achievable with asynchronous replication — there is always a small lag (typically under 1 second).',
      B: 'Standard RDS cross-region read replica promotion takes longer — Aurora Global Database is specifically designed for fast managed failover.'
    } },
  { id: 'd2-dr-006', domain: 2, topics: ['DR', 'AWS Elastic Disaster Recovery'], type: 'single', stem: 'A company wants to continuously replicate on-premises servers to AWS and launch recovery instances within minutes during a disaster. What AWS service provides this?', options: [{ id: 'A', text: 'AWS Backup' }, { id: 'B', text: 'AWS Storage Gateway' }, { id: 'C', text: 'AWS Elastic Disaster Recovery (DRS)' }, { id: 'D', text: 'AWS DataSync' }], correct: ['C'], explanation: 'AWS DRS (formerly CloudEndure Disaster Recovery) continuously replicates block storage from on-premises or cloud servers to AWS. On failover, recovery instances are launched in minutes from the latest replicated state — sub-second RPO.', distractors: {
      A: 'AWS Backup manages snapshots and backups — not continuous block-level server replication for DR.',
      B: 'Storage Gateway provides hybrid cloud storage (file/block/tape) — not server replication for quick DR recovery.',
      D: 'DataSync transfers file data between storage locations — not a full-server continuous replication DR service.'
    } },
  { id: 'd2-dr-007', domain: 2, topics: ['DR', 'warm standby', 'failover steps'], type: 'single', stem: 'A company uses Warm Standby DR. A disaster occurs and failover is initiated. What must happen to serve full production traffic?', options: [{ id: 'A', text: 'Scale up the DR environment: increase ASG sizes to production, promote DB read replica, update Route 53 records to DR region' }, { id: 'B', text: 'Contact AWS Support to provision additional capacity' }, { id: 'C', text: 'Nothing additional' }, { id: 'D', text: 'Restore from the latest backup and rebuild infrastructure from IaC templates in the DR region' }], correct: ['A'], explanation: 'Warm Standby runs at minimum capacity (e.g., ASG min=1, smaller instance). On failover: scale up ASG to production sizes, promote the read replica to primary, update Route 53 to DR region DNS. Faster than Pilot Light since environment is already running.', distractors: {
      C: 'Active-Active is at full capacity — Warm Standby is intentionally at reduced capacity to save cost.',
      D: 'Restoring from backups is the Backup and Restore strategy — Warm Standby has a live minimal environment that needs scaling, not rebuilding.',
      B: 'No AWS Support involvement — scaling is done via Auto Scaling, RDS promotion, and Route 53 updates.'
    } },
  { id: 'd2-dr-008', domain: 2, topics: ['DR', 'S3 CRR'], type: 'single', stem: 'As part of a DR strategy, all S3 data should replicate to another region automatically and continuously. What is the appropriate approach?', options: [{ id: 'A', text: 'Daily scheduled AWS CLI s3 sync scripts to copy objects to the DR region bucket' }, { id: 'B', text: 'S3 Transfer Acceleration' }, { id: 'C', text: 'Manually export objects before a disaster and import to the DR region when needed' }, { id: 'D', text: 'S3 Cross-Region Replication (CRR)' }], correct: ['D'], explanation: 'S3 CRR continuously replicates objects to a destination bucket in another region. For DR, enable Delete Marker Replication and consider Replication Time Control for an SLA (99.99% of objects replicated in 15 minutes). Requires versioning on both buckets.', distractors: {
      A: 'Daily sync scripts have up to 24-hour RPO and require maintenance — CRR provides continuous automatic replication.',
      C: 'Manual copying before a disaster is not a valid DR strategy — disasters are unscheduled and unpredictable.',
      B: 'Transfer Acceleration speeds uploads to a single bucket — it does not replicate objects between buckets or regions.'
    } },
  { id: 'd2-dr-009', domain: 2, topics: ['DR', 'RDS', 'cross-region read replica'], type: 'single', stem: 'A company has RDS MySQL in us-east-1 and needs a continuously synchronized DR database in eu-west-1. On failover, the EU database becomes the primary. What is the architecture?', options: [{ id: 'A', text: 'RDS automated snapshot copy to eu-west-1' }, { id: 'B', text: 'AWS DMS continuous replication to RDS in eu-west-1' }, { id: 'C', text: 'RDS Cross-Region Read Replica in eu-west-1' }, { id: 'D', text: 'RDS Multi-AZ in us-east-1' }], correct: ['C'], explanation: 'Cross-region read replicas continuously replicate asynchronously. On failover, promote the read replica to a standalone RDS instance. Update the application connection string. RPO equals the replication lag (seconds to minutes for low-traffic periods).', distractors: {
      D: 'Multi-AZ is within a single region — doesn\'t provide cross-region DR protection.',
      A: 'Snapshot copies are point-in-time (RPO = time since last snapshot) — not continuously synchronized.',
      B: 'DMS is a migration/replication tool but more complex to manage vs. native RDS cross-region read replicas.'
    } },
  { id: 'd2-dr-010', domain: 2, topics: ['DR', 'AMI', 'cross-region prep'], type: 'single', stem: 'A DR plan requires launching EC2 instances in a secondary region within 15 minutes. What should be prepared in advance to enable this?', options: [{ id: 'A', text: 'Pre-copy AMIs to the secondary region and prepare CloudFormation/Terraform templates for rapid deployment from pre-staged AMIs' }, { id: 'B', text: 'Run EC2 instances continuously in the secondary region' }, { id: 'C', text: 'Open an AWS Support case to reserve instance capacity in advance of a potential disaster event' }, { id: 'D', text: 'Use EC2 Spot Instances in the secondary region' }], correct: ['A'], explanation: 'Pre-copying AMIs to the DR region eliminates the AMI copy time during a disaster. With IaC templates ready, instances can launch within the RTO window. Test the runbook regularly to validate actual launch times.', distractors: {
      B: 'Running instances 24/7 is Warm Standby — expensive if a minimal RTO doesn\'t require it.',
      D: 'Spot Instances can be interrupted by AWS at any time — not reliable as the sole DR compute source.',
      C: 'AWS Support is not the mechanism — use Capacity Reservations proactively if guaranteed capacity is needed.'
    } },
  { id: 'd2-dr-011', domain: 2, topics: ['DR', 'chaos engineering', 'AWS FIS'], type: 'single', stem: 'A company wants to test their DR procedures by simulating infrastructure failures in a controlled way. Which AWS service enables this?', options: [{ id: 'A', text: 'AWS Config' }, { id: 'B', text: 'AWS Trusted Advisor' }, { id: 'C', text: 'AWS CloudTrail' }, { id: 'D', text: 'AWS Fault Injection Simulator (FIS)' }], correct: ['D'], explanation: 'AWS FIS enables chaos engineering by injecting controlled failures: terminate EC2 instances, throttle CPU, inject network latency, cause AZ failures. Tests DR runbooks and identifies gaps before actual disasters occur.', distractors: {
      A: 'AWS Config monitors configuration compliance — not failure injection for DR testing.',
      C: 'CloudTrail logs API calls — not a failure simulation tool for DR testing.',
      B: 'Trusted Advisor provides recommendations — not controlled failure injection for DR validation.'
    } },
  { id: 'd2-dr-012', domain: 2, topics: ['DR', 'AWS Backup', 'centralized'], type: 'single', stem: 'A company needs centralized backup management across EC2, RDS, EFS, DynamoDB, and EBS across multiple AWS accounts. What service provides this?', options: [{ id: 'A', text: 'AWS Backup' }, { id: 'B', text: 'S3 Lifecycle rules' }, { id: 'C', text: 'EC2 snapshot automation' }, { id: 'D', text: 'Separate native backup solutions per service' }], correct: ['A'], explanation: 'AWS Backup provides centralized backup management: define backup plans applied to EC2, RDS, Aurora, DynamoDB, EFS, FSx, and EBS. Supports cross-region and cross-account backup copies for DR compliance.', distractors: {
      D: 'Service-specific backup solutions require separate management policies, monitoring, and compliance reporting — AWS Backup centralizes all of this.',
      B: 'S3 lifecycle rules manage S3 object transitions — cannot back up EC2, RDS, DynamoDB, or EFS.',
      C: 'Data Lifecycle Manager handles EBS/EC2 snapshots only — not the full cross-service coverage needed.'
    } },
  { id: 'd2-dr-013', domain: 2, topics: ['DR', 'DynamoDB', 'global tables'], type: 'single', stem: 'A company uses DynamoDB and requires multi-region active-active writes where writes in any region are automatically synchronized everywhere. What DynamoDB feature enables this?', options: [{ id: 'A', text: 'DynamoDB Cross-Region Read Replicas' }, { id: 'B', text: 'DynamoDB Streams' }, { id: 'C', text: 'DynamoDB Global Tables' }, { id: 'D', text: 'DynamoDB Multi-AZ' }], correct: ['C'], explanation: 'DynamoDB Global Tables provides active-active multi-region replication. Write in any region; changes replicate to all regions within typically under 1 second using last-writer-wins conflict resolution.', distractors: {
      A: 'DynamoDB doesn\'t have a concept called "Cross-Region Read Replicas" — Global Tables is the multi-region solution.',
      B: 'DynamoDB Streams capture changes and are used internally by Global Tables — by themselves, Streams require custom replication code.',
      D: 'DynamoDB is automatically multi-AZ within a region — Global Tables extends replication across regions.'
    } },
  { id: 'd2-dr-014', domain: 2, topics: ['DR', 'AZ failure', 'multi-AZ architecture'], type: 'single', stem: 'An application must survive a single AZ failure with zero data loss and automatic recovery. What is the minimum architecture requirement?', options: [{ id: 'A', text: 'Multi-AZ deployment: EC2 across 2+ AZs with Auto Scaling, RDS Multi-AZ' }, { id: 'B', text: 'Single EC2 instance with CloudWatch enhanced monitoring' }, { id: 'C', text: 'EC2 cluster placement group' }, { id: 'D', text: 'Multi-Region Active-Active' }], correct: ['A'], explanation: 'Multi-AZ: RDS Multi-AZ automatically fails over to the standby. Auto Scaling across AZs replaces terminated instances in healthy AZs. This is the baseline HA architecture for surviving single-AZ failures.', distractors: {
      B: 'A single EC2 instance is a single point of failure — it fails completely if the AZ goes down.',
      D: 'Multi-Region Active-Active handles full regional outages — far more expensive than needed for single-AZ resilience.',
      C: 'Cluster placement groups concentrate instances in the same AZ for low latency — this actually increases AZ failure risk.'
    } },
  { id: 'd2-dr-015', domain: 2, topics: ['DR', 'EBS snapshots', 'cross-region copy'], type: 'single', stem: 'A DR strategy requires EBS volumes to be available in a secondary region. How are EBS snapshots made available cross-region?', options: [{ id: 'A', text: 'Use S3 to replicate EBS block data by mounting the volume and exporting block data to S3 manually' }, { id: 'B', text: 'EBS snapshots stored in S3 are global and accessible from any region automatically' }, { id: 'C', text: 'EBS volumes automatically synchronize cross-region when Multi-AZ is enabled on the instance' }, { id: 'D', text: 'Copy EBS snapshots to the secondary region using the CopySnapshot API' }], correct: ['D'], explanation: 'EBS snapshots can be copied to other regions using CopySnapshot API or AWS Backup cross-region copy rules. The copied snapshot can be used to restore EBS volumes in the target region during DR.', distractors: {
      C: 'EBS volumes are AZ-scoped resources — no automatic cross-region replication exists.',
      A: 'EBS snapshots are managed by AWS and stored internally — you use the EBS snapshot copy mechanism, not manual block data export.',
      B: 'EBS snapshots are regional resources — they are not automatically global or accessible from other regions.'
    } },
  { id: 'd2-dr-016', domain: 2, topics: ['DR', 'RPO definition'], type: 'single', stem: 'What does Recovery Point Objective (RPO) measure in disaster recovery planning?', options: [{ id: 'A', text: 'The maximum acceptable data loss measured in time' }, { id: 'B', text: 'The total monthly cost of maintaining the DR environment in a secondary region' }, { id: 'C', text: 'The maximum number of failed requests allowed before automatic failover is triggered' }, { id: 'D', text: 'The maximum acceptable time to restore systems to full operation after a disaster event' }], correct: ['A'], explanation: 'RPO is the maximum acceptable data loss measured in time. RPO=1 hour means tolerating up to 1 hour of lost data. Lower RPO requires more frequent backups or continuous replication, increasing cost.', distractors: {
      D: 'Time to restore systems is RTO (Recovery Time Objective) — RPO measures data loss, not downtime duration.',
      B: 'DR environment cost is a business consideration — not what RPO measures.',
      C: 'Request failure thresholds relate to availability SLAs — not the definition of RPO.'
    } },
  { id: 'd2-dr-017', domain: 2, topics: ['DR', 'RTO definition'], type: 'single', stem: 'What does Recovery Time Objective (RTO) measure in disaster recovery planning?', options: [{ id: 'A', text: 'Maximum acceptable data loss' }, { id: 'B', text: 'Maximum acceptable downtime' }, { id: 'C', text: 'The configured interval between automated backup operations' }, { id: 'D', text: 'The time required to replicate data to the secondary DR region during normal operations' }], correct: ['B'], explanation: 'RTO is the maximum acceptable downtime — how long can the system be unavailable? Lower RTO requires faster failover mechanisms (warm standby, active-active) and costs more to maintain.', distractors: { A: 'Maximum data loss is RPO — RTO measures the duration of acceptable downtime, not data loss.', C: 'Backup interval determines achievable RPO — not a definition of RTO.', D: 'Replication time affects the achievable RPO — not the definition of RTO.' } },
  { id: 'd2-dr-018', domain: 2, topics: ['DR', 'serverless', 'low RTO'], type: 'single', stem: 'A company runs a serverless application with Lambda, API Gateway, and DynamoDB. What is a key DR advantage of serverless over EC2-based architectures?', options: [{ id: 'A', text: 'DynamoDB tables are automatically replicated globally to all regions by default on creation' }, { id: 'B', text: 'Serverless applications have no DR requirements' }, { id: 'C', text: 'Serverless infrastructure deploys in seconds via IaC' }, { id: 'D', text: 'Lambda is automatically deployed globally to all regions when created in one region' }], correct: ['C'], explanation: 'Serverless has minimal infrastructure state. Lambda code, API Gateway, and DynamoDB can be deployed in seconds via CloudFormation in the DR region. With DynamoDB Global Tables, data is already replicated. RTO can be minutes or even seconds.', distractors: {
      B: 'Serverless apps still require DR planning — regional failures affect Lambda, API Gateway, and DynamoDB.',
      D: 'Lambda functions must be explicitly deployed in each region — no automatic global deployment.',
      A: 'DynamoDB Global Tables must be explicitly configured — DynamoDB is not automatically replicated globally.'
    } },
  { id: 'd2-dr-019', domain: 2, topics: ['DR', 'SQS', 'message durability'], type: 'single', stem: 'During a regional failure, SQS producers continue sending messages but consumers are down. How does SQS contribute to resilience when consumers recover?', options: [{ id: 'A', text: 'SQS detects consumer failures and automatically fails over to a DR region consumer endpoint' }, { id: 'B', text: 'SQS messages are lost when no consumer acknowledges them within the visibility timeout period' }, { id: 'C', text: 'SQS automatically replicates queues cross-region so the DR region receives messages during primary failure' }, { id: 'D', text: 'SQS durably stores messages for up to 14 days' }], correct: ['D'], explanation: 'SQS stores messages for up to 14 days. If consumers fail, messages queue up durably. When consumers recover (same or different region, depending on architecture), they process the accumulated backlog. Decoupling is the key resilience pattern.', distractors: {
      C: 'SQS queues are regional — they don\'t automatically replicate cross-region.',
      A: 'SQS doesn\'t auto-failover to a different region consumer — the decoupling pattern handles this by preserving messages until consumers are ready.',
      B: 'SQS visibility timeout controls when messages become visible again for re-processing — messages are not lost, they return to the queue.'
    } },
  { id: 'd2-dr-020', domain: 2, topics: ['DR', 'IaC', 'CloudFormation'], type: 'single', stem: 'A company wants to recover their entire infrastructure in a secondary region during a regional disaster. What ensures infrastructure can be rebuilt reliably and quickly?', options: [{ id: 'A', text: 'A detailed runbook document with step-by-step console instructions for each resource' }, { id: 'B', text: 'Annotated screenshots of the AWS Management Console configuration for reference' }, { id: 'C', text: 'Infrastructure as Code (CloudFormation/Terraform)' }, { id: 'D', text: 'Spreadsheet exports of all service configurations for manual re-entry during recovery' }], correct: ['C'], explanation: 'IaC templates can deploy the complete infrastructure in any region in minutes, idempotently and without human error. Runbooks, screenshots, and spreadsheets are prone to outdated information and human error under pressure.', distractors: {
      A: 'Runbooks depend on human accuracy and staying current as the infrastructure evolves — IaC is automated and version-controlled.',
      B: 'Screenshots become stale immediately after any configuration change and require manual interpretation.',
      D: 'Spreadsheet re-entry is slow, error-prone, and doesn\'t capture resource dependencies or ordering.'
    } },
  { id: 'd2-dr-021', domain: 2, topics: ['DR', 'strategy comparison', 'cost vs RTO'], type: 'single', stem: 'Rank these DR strategies from LOWEST to HIGHEST cost (inversely from HIGHEST to LOWEST RTO):', options: [{ id: 'A', text: 'Backup and Restore < Pilot Light < Warm Standby < Active-Active (low to high cost)' }, { id: 'B', text: 'Warm Standby < Pilot Light < Active-Active < Backup and Restore (low to high cost)' }, { id: 'C', text: 'Active-Active > Warm Standby > Pilot Light > Backup and Restore (high to low cost)' }, { id: 'D', text: 'Pilot Light < Backup and Restore < Active-Active < Warm Standby (low to high cost)' }], correct: ['A'], explanation: 'DR cost spectrum (lowest to highest): Backup and Restore (cheapest, hours RTO) → Pilot Light (core services only) → Warm Standby (scaled-down running environment) → Active-Active (full dual-region, lowest RTO).', distractors: {
      C: 'This is the correct ranking in reverse (high to low cost) — the question asks low to high cost.',
      D: 'Pilot Light always costs more than Backup and Restore — Pilot Light keeps core services running, B&R has no running resources.',
      B: 'The ranking is incorrect — Backup and Restore is the cheapest, not the most expensive.'
    } },
  { id: 'd2-dr-022', domain: 2, topics: ['DR', 'auto scaling', 'AZ resilience'], type: 'single', stem: 'An application runs on a single EC2 instance in one AZ. An AZ outage causes a 4-hour outage. What is the minimum architectural change to survive an AZ failure with automatic recovery?', options: [{ id: 'A', text: 'Enable CloudWatch detailed monitoring on the EC2 instance for faster failure detection' }, { id: 'B', text: 'Enable Multi-AZ on the EC2 instance configuration' }, { id: 'C', text: 'Assign an Elastic IP to the instance' }, { id: 'D', text: 'Place the EC2 instance in an Auto Scaling group spanning multiple AZs' }], correct: ['D'], explanation: 'An ASG with desired=1 spanning multiple AZs detects unhealthy instances and launches replacements in healthy AZs. The data/state must also be accessible from the new AZ (use EFS or RDS instead of local EBS).', distractors: {
      A: 'Detailed monitoring improves detection speed — but a single-instance AZ failure still causes an outage until manual intervention.',
      C: 'EIP remapping requires manual action or custom scripts — ASG provides fully automatic replacement.',
      B: 'Multi-AZ is an RDS database concept — EC2 uses Auto Scaling groups across AZs for resilience.'
    } },
  { id: 'd2-dr-023', domain: 2, topics: ['DR', 'EFS', 'shared storage'], type: 'single', stem: 'An application requires shared file storage accessible from EC2 instances in multiple AZs. If one AZ fails, instances in other AZs must continue accessing the same files. What service provides this?', options: [{ id: 'A', text: 'Amazon EFS' }, { id: 'B', text: 'Instance store volumes' }, { id: 'C', text: 'S3 with FUSE mount' }, { id: 'D', text: 'EBS volume shared across multiple instances' }], correct: ['A'], explanation: 'EFS provides regional NFS file storage with mount targets in each AZ. If one AZ fails, instances in other AZs continue accessing the same EFS file system through mount targets in their respective AZs — single shared file system across AZs.', distractors: {
      D: 'EBS volumes are AZ-scoped and can only be Multi-Attached within a single AZ — not shared across AZs.',
      C: 'S3 FUSE has performance limitations and consistency caveats — EFS is designed specifically for NFS workloads.',
      B: 'Instance store is ephemeral local storage attached to a single instance — no sharing and data is lost when instance stops.'
    } },
  { id: 'd2-dr-024', domain: 2, topics: ['DR', 'EC2 auto recovery', 'system checks'], type: 'single', stem: 'A critical EC2 instance must automatically recover if underlying hardware fails, retaining the same private IP, instance ID, and EBS volumes. What feature provides this?', options: [{ id: 'A', text: 'EBS Multi-Attach' }, { id: 'B', text: 'EC2 Auto Recovery' }, { id: 'C', text: 'Auto Scaling group with minimum 1' }, { id: 'D', text: 'Elastic IP reassignment via Lambda' }], correct: ['B'], explanation: 'EC2 Auto Recovery recovers the instance on different hardware while retaining instance ID, private/Elastic IP, and all EBS volumes. Requires EBS-backed storage. A CloudWatch alarm on StatusCheckFailed:System triggers the recovery action.', distractors: {
      C: 'ASG creates new instances with new IDs and potentially different IPs — retaining instance identity requires Auto Recovery.',
      A: 'EBS Multi-Attach allows concurrent volume access from multiple instances — not a failure recovery mechanism.',
      D: 'Custom EIP reassignment via Lambda requires engineering and has latency — Auto Recovery is fully managed.'
    } },
  { id: 'd2-dr-025', domain: 2, topics: ['DR', 'SQS', 'cascading failures'], type: 'single', stem: 'During high traffic, downstream order processors fail and fall behind. The failure cascades upstream causing the order API to also fail. Which pattern prevents cascading failures?', options: [{ id: 'A', text: 'Enable Multi-AZ on all services to prevent individual service failures from cascading' }, { id: 'B', text: 'Synchronous processing with retry loops' }, { id: 'C', text: 'Asynchronous processing with SQS' }, { id: 'D', text: 'Scale up all instance sizes to handle the load surge and prevent failures' }], correct: ['C'], explanation: 'SQS decouples services. If the order processor fails, messages queue up — the API layer continues accepting orders. When the processor recovers, it drains the backlog. Synchronous calls propagate failures upstream; queues absorb them.', distractors: {
      B: 'Synchronous retry loops block the calling service waiting for the downstream — failure cascades up the call chain.',
      D: 'Larger instances handle more load but are still susceptible to failure — decoupling with SQS is the architectural fix.',
      A: 'Multi-AZ provides infrastructure HA — it doesn\'t prevent service-level cascading failures from application bugs or overload.'
    } },
  { id: 'd2-dr-026', domain: 2, topics: ['DR', 'RDS snapshot restore'], type: 'single', stem: 'What happens to the original RDS instance when it is restored from a snapshot?', options: [{ id: 'A', text: 'The original instance is replaced in-place with the snapshot data' }, { id: 'B', text: 'The snapshot overwrites data in the original instance' }, { id: 'C', text: 'Only the changed data since the snapshot is applied to the existing instance' }, { id: 'D', text: 'A new RDS instance is created' }], correct: ['D'], explanation: 'Restoring from an RDS snapshot always creates a NEW DB instance with a new endpoint. The original instance continues running unaffected. After restoration, update the connection string and verify data integrity before switching traffic.', distractors: {
      A: 'RDS snapshot restore is not in-place — it creates a new instance; the original is untouched.',
      C: 'RDS snapshot restore creates a complete new instance from the full snapshot — not an incremental apply to the existing instance.',
      B: 'The snapshot never affects the existing instance — they can coexist, and the original remains unchanged.'
    } },
  { id: 'd2-dr-027', domain: 2, topics: ['DR', 'stateless design', 'multi-region'], type: 'single', stem: 'A company wants to make their application easily deployable in any region for DR. What architectural principle minimizes cross-region deployment complexity?', options: [{ id: 'A', text: 'Design stateless application tiers' }, { id: 'B', text: 'Use one large EC2 instance for all components' }, { id: 'C', text: 'Avoid Infrastructure as Code' }, { id: 'D', text: 'Store all session and application state locally in EC2 instance memory for fastest access' }], correct: ['A'], explanation: 'Stateless application tiers (Lambda, ECS, EC2 without local state) are trivially redeployable — run the same container/code in a new region. State lives in managed services with cross-region replication (DynamoDB Global Tables, Aurora Global DB, S3 CRR).', distractors: {
      D: 'Local state on EC2 is lost on instance replacement and cannot be moved cross-region — tight coupling to a single host.',
      B: 'A monolithic large instance creates a single point of failure and cannot scale independently by component.',
      C: 'IaC is essential for repeatable, reliable multi-region deployments — manual setup is error-prone and slow under DR pressure.'
    } },
  { id: 'd2-dr-028', domain: 2, topics: ['DR', 'DR testing', 'runbook validation'], type: 'single', stem: 'A company has a DR plan that has never been tested. What is the biggest risk of an untested DR plan?', options: [{ id: 'A', text: 'DR testing causes real production outages and should be avoided unless absolutely necessary' }, { id: 'B', text: 'The actual RTO/RPO is often much worse than planned' }, { id: 'C', text: 'AWS managed services don\'t require DR testing' }, { id: 'D', text: 'DR testing is only recommended for Tier 1 critical applications' }], correct: ['B'], explanation: 'Untested DR plans frequently fail in practice: outdated runbooks, undocumented dependencies, missing IAM permissions, stale AMIs, and human errors under pressure. Regular testing (game days, FIS chaos engineering) validates actual RTO/RPO metrics.', distractors: {
      C: 'AWS managed services handle infrastructure failures automatically — but application-level DR (connection strings, data validation, runbooks) still requires testing.',
      A: 'DR drills use isolated or non-production environments — properly designed tests don\'t cause production outages.',
      D: 'All applications benefit from DR testing — even non-critical ones can cause cascading failures when they become unavailable.'
    } },
  { id: 'd2-dr-029', domain: 2, topics: ['DR', 'AWS Health'], type: 'single', stem: 'A company needs proactive notification when AWS services they use experience issues that could affect their specific resources. What service provides personalized AWS health events?', options: [{ id: 'A', text: 'AWS Health' }, { id: 'B', text: 'CloudWatch alarms' }, { id: 'C', text: 'AWS Config' }, { id: 'D', text: 'AWS Service Health Dashboard' }], correct: ['A'], explanation: 'AWS Health provides personalized notifications about AWS events that specifically affect your accounts and resources — not just general service status. Integrate with EventBridge to automate DR responses to health events.', distractors: {
      B: 'CloudWatch alarms monitor your own application metrics — not AWS service health events affecting AWS infrastructure.',
      D: 'Service Health Dashboard shows general public AWS status — AWS Health shows events affecting YOUR specific resources.',
      C: 'Config tracks configuration compliance — not AWS service health events.'
    } },
  { id: 'd2-dr-030', domain: 2, topics: ['DR', 'AWS Resilience Hub'], type: 'single', stem: 'A company wants AWS to automatically assess their application against defined RTO/RPO targets and identify gaps in their DR architecture. What service provides this?', options: [{ id: 'A', text: 'AWS Resilience Hub' }, { id: 'B', text: 'AWS Config' }, { id: 'C', text: 'AWS Security Hub' }, { id: 'D', text: 'AWS Trusted Advisor' }], correct: ['A'], explanation: 'AWS Resilience Hub lets you define RTO/RPO targets and automatically assesses your application architecture against them. Identifies resilience gaps (no Multi-AZ, missing replicas), provides recommendations, and generates recovery runbooks.', distractors: {
      D: 'Trusted Advisor provides general best practices — not RTO/RPO-specific application resilience assessment.',
      B: 'Config evaluates resource configuration compliance — not application-level resilience against RTO/RPO targets.',
      C: 'Security Hub aggregates security findings — not DR resilience assessment against RTO/RPO metrics.'
    } },
  { id: 'd2-dr-031', domain: 2, topics: ['DR', 'Direct Connect', 'VPN failover'], type: 'single', stem: 'A company has Direct Connect as primary connectivity to AWS. If Direct Connect fails, the network connection should automatically fail over to a backup Site-to-Site VPN. What provides automatic failover between these two?', options: [{ id: 'A', text: 'Route 53 failover routing' }, { id: 'B', text: 'Configure both Direct Connect and Site-to-Site VPN with BGP routing' }, { id: 'C', text: 'AWS Global Accelerator' }, { id: 'D', text: 'CloudFront origin failover' }], correct: ['B'], explanation: 'The resilient hybrid network pattern: Direct Connect as primary, Site-to-Site VPN as backup. Configure BGP metrics so DX routes are more specific and preferred. When DX fails, BGP automatically falls back to VPN routes. Transit Gateway simplifies this routing.', distractors: { A: 'Route 53 is DNS-layer routing — not network-layer Direct Connect/VPN failover.', C: 'Global Accelerator routes application traffic via Anycast IPs — not on-premises network connectivity failover.', D: 'CloudFront origin failover is for CDN origin selection — not enterprise network connectivity between premises and AWS.' } },
  { id: 'd2-dr-032', domain: 2, topics: ['DR', 'ElastiCache', 'Global Datastore'], type: 'single', stem: 'A company uses ElastiCache Redis for session caching and needs cache data available in a secondary DR region with continuous replication. What ElastiCache feature provides this?', options: [{ id: 'A', text: 'ElastiCache Serverless' }, { id: 'B', text: 'ElastiCache Multi-AZ' }, { id: 'C', text: 'ElastiCache Global Datastore' }, { id: 'D', text: 'ElastiCache automated backup export to secondary region S3 bucket' }], correct: ['C'], explanation: 'ElastiCache Global Datastore for Redis provides cross-region replication: a primary cluster in one region replicates to read-only secondary clusters in other regions. On failover, promote the secondary to primary for active use.', distractors: {
      B: 'Multi-AZ provides HA within a single region — does not extend replication to a secondary DR region.',
      D: 'Backup and restore to S3 has point-in-time RPO measured in hours — Global Datastore is continuous.',
      A: 'ElastiCache Serverless automatically manages capacity — it doesn\'t provide cross-region replication.'
    } },
  { id: 'd2-dr-033', domain: 2, topics: ['DR', 'session state', 'externalized'], type: 'single', stem: 'During failover to a DR region, user sessions stored in EC2 memory are lost and users are logged out. How should sessions be managed for DR resilience?', options: [{ id: 'A', text: 'Use ALB sticky sessions' }, { id: 'B', text: 'Disable user sessions entirely' }, { id: 'C', text: 'Increase EC2 instance memory' }, { id: 'D', text: 'Externalize sessions to ElastiCache or DynamoDB' }], correct: ['D'], explanation: 'Externalized session state (ElastiCache Redis or DynamoDB) decouples sessions from EC2. During failover, sessions persist in the external store (replicated to DR region via Global Datastore or Global Tables). Users retain sessions even as instances change.', distractors: {
      C: 'Larger instances are still single hosts — any instance or AZ failure loses in-memory sessions regardless of size.',
      A: 'Sticky sessions bind users to specific instances — if that instance fails during DR failover, the session is still lost.',
      B: 'Sessions provide critical user experience (auth state) — disabling them is not a practical DR strategy.'
    } },
  { id: 'd2-dr-034', domain: 2, topics: ['DR', 'S3 versioning', 'accidental deletion'], type: 'single', stem: 'A script accidentally deletes all objects in a production S3 bucket. The company needs to recover all objects immediately. What S3 feature was required to have been configured beforehand?', options: [{ id: 'A', text: 'S3 versioning' }, { id: 'B', text: 'S3 Storage Class Analysis' }, { id: 'C', text: 'S3 Lifecycle rules' }, { id: 'D', text: 'S3 CRR' }], correct: ['A'], explanation: 'With versioning enabled, deleting objects creates delete markers (doesn\'t permanently delete). Recover all objects by removing the delete markers. Without versioning, the deletion is permanent and unrecoverable.', distractors: {
      D: 'CRR also replicates delete markers by default — both buckets would have deleted objects. Versioning in the destination could save them if delete marker replication is disabled.',
      C: 'Lifecycle rules can transition/expire objects — they don\'t prevent deletion and aren\'t a recovery mechanism.',
      B: 'Storage Class Analysis monitors access patterns — not a deletion protection or recovery feature.'
    } },
  { id: 'd2-dr-035', domain: 2, topics: ['DR', 'automation', 'RTO reduction'], type: 'single', stem: 'A DR runbook has 20 manual steps taking 2-3 hours to complete. How should the RTO be reduced to under 30 minutes?', options: [{ id: 'A', text: 'Hire additional operations staff to execute runbook steps in parallel' }, { id: 'B', text: 'Automate the DR runbook using Systems Manager Automation, Lambda, or Step Functions' }, { id: 'C', text: 'Reduce the number of AWS services in the architecture to simplify the runbook' }, { id: 'D', text: 'Renegotiate the SLA to accept the current 2-3 hour RTO as acceptable for business' }], correct: ['B'], explanation: 'Automation transforms multi-hour manual runbooks into reliable, fast automated workflows. AWS Systems Manager Automation, Lambda, and Step Functions can automate: promote DB replicas, update Route 53, scale ASGs, validate health checks.', distractors: { A: 'More staff can parallelize some steps but human coordination still takes time — automation is fundamentally faster and error-free.', C: 'Fewer services simplifies the DR process but reduces functionality — automation addresses the manual execution problem directly.', D: 'Accepting a high RTO for critical services is a business risk — automation is the technical solution.' } },
  { id: 'd2-dr-036', domain: 2, topics: ['DR', 'ECR', 'container images'], type: 'single', stem: 'A company runs EKS workloads and container images are in ECR in us-east-1. For DR in eu-west-1, container images must be available locally. What ensures images are available in the DR region?', options: [{ id: 'A', text: 'Configure ECR cross-region replication' }, { id: 'B', text: 'Pull images from us-east-1 ECR from eu-west-1 EKS during the DR event' }, { id: 'C', text: 'ECR is a global service' }, { id: 'D', text: 'Rebuild container images from source code in eu-west-1 as part of the DR failover procedure' }], correct: ['A'], explanation: 'ECR registries are regional resources. Configure ECR cross-region replication to automatically push images to eu-west-1. Pre-staged images ensure fast DR deployment without cross-region pull delays or dependencies on the failed region.', distractors: {
      C: 'ECR is regional — not a global service with automatic cross-region availability.',
      D: 'Rebuilding images during a DR event adds significant RTO and may fail if the source code repository or CI/CD pipeline is also affected.',
      B: 'Pulling from us-east-1 during DR creates a dependency on the region that might have failed — the reason for DR.'
    } },
  { id: 'd2-dr-037', domain: 2, topics: ['DR', 'ARC', 'Application Recovery Controller'], type: 'single', stem: 'A company needs fine-grained DR routing control with safety rules and pre-failover readiness verification across regions and AZs. What AWS service provides this?', options: [{ id: 'A', text: 'Route 53 failover routing' }, { id: 'B', text: 'AWS Auto Scaling' }, { id: 'C', text: 'CloudFormation StackSets' }, { id: 'D', text: 'AWS Application Recovery Controller (ARC)' }], correct: ['D'], explanation: 'AWS ARC provides: (1) Routing Control — flip traffic between regions/AZs via Route 53 health checks with safety rules preventing unsafe failovers. (2) Readiness Check — validates DR infrastructure is ready. (3) Zonal Shift — quickly move traffic away from impaired AZs.', distractors: {
      A: 'Route 53 failover handles DNS routing but lacks ARC\'s safety rules, readiness checks, and structured failover orchestration.',
      B: 'Auto Scaling manages instance capacity — not DR routing control between regions.',
      C: 'StackSets deploy infrastructure multi-region — not DR traffic routing or readiness validation.'
    } },
  { id: 'd2-dr-038', domain: 2, topics: ['DR', 'failover pre-checks', 'readiness'], type: 'single', stem: 'Before executing a DR failover to a secondary region, which checks must be completed to avoid a failed failover?', options: [{ id: 'A', text: 'Verify: database replica lag, application deployment status, IAM/security group parity, DNS TTLs lowered, reserved capacity' }, { id: 'B', text: 'Only verify Route 53 health checks are green before updating DNS records' }, { id: 'C', text: 'Immediately update DNS to DR region without pre-checks to minimize failover time and user impact' }, { id: 'D', text: 'Only verify that EC2 instances are in running state in the secondary region' }], correct: ['A'], explanation: 'Complete DR readiness verification: DB replica lag (is data current?), application version deployed in DR, security configs match (SGs, NACLs, IAM), DNS TTLs reduced, sufficient capacity reserved. ARC Readiness Checks formalize this process.', distractors: {
      D: 'EC2 running state is necessary but insufficient — database data currency and application code deployment are also critical.',
      C: 'Updating DNS to an unready environment fails both the DR and the users — pre-validation is essential before cutover.',
      B: 'Route 53 health checks verify application availability — insufficient alone for comprehensive DR readiness.'
    } },
  { id: 'd2-dr-039', domain: 2, topics: ['DR', 'AWS Config', 'DR compliance'], type: 'single', stem: 'A company wants to continuously detect when DR best practices are not followed (e.g., RDS without Multi-AZ, EBS without backups). What service enforces ongoing DR compliance?', options: [{ id: 'A', text: 'Amazon Inspector' }, { id: 'B', text: 'AWS Config rules' }, { id: 'C', text: 'AWS CloudTrail' }, { id: 'D', text: 'Amazon GuardDuty' }], correct: ['B'], explanation: 'AWS Config managed rules (e.g., rds-multi-az-support, ec2-volume-inuse-check) continuously monitor for DR compliance. Non-compliant resources trigger rules that alert via SNS or auto-remediate via Systems Manager.', distractors: {
      C: 'CloudTrail logs API calls for audit — not continuous configuration compliance evaluation against DR rules.',
      A: 'Inspector scans for software vulnerabilities and CIS benchmarks — not DR configuration gaps like missing Multi-AZ.',
      D: 'GuardDuty detects threats like compromised credentials — not DR compliance like missing backups.'
    } },
  { id: 'd2-dr-040', domain: 2, topics: ['DR', 'Global Accelerator', 'fast failover'], type: 'single', stem: 'A company needs application-layer failover between regions in under 30 seconds using static IP addresses that never change. What service provides this?', options: [{ id: 'A', text: 'Route 53 with 30-second TTL' }, { id: 'B', text: 'NAT Gateway in DR region' }, { id: 'C', text: 'CloudFront with origin failover' }, { id: 'D', text: 'AWS Global Accelerator' }], correct: ['D'], explanation: 'Global Accelerator provides two static Anycast IPs. Traffic enters AWS network at the nearest edge. Health checks detect failures and reroute in seconds. No DNS TTL delays since clients use the same static IPs — no DNS cache to wait for.', distractors: {
      A: 'Route 53 with 30s TTL still requires DNS cache expiry — some clients ignore TTLs and cache longer, causing unpredictable failover.',
      C: 'CloudFront origin failover is for CDN origin selection — not application-level multi-region failover with static IPs.',
      B: 'NAT Gateway handles outbound internet access — not inbound application-level DR routing with static IPs.'
    } },
  { id: 'd2-dr-041', domain: 2, topics: ['DR', 'EFS replication'], type: 'single', stem: 'An EFS file system stores critical application data. For DR, data must be continuously replicated to a secondary region with near-zero RPO. How is EFS cross-region replication configured?', options: [{ id: 'A', text: 'Enable EFS Replication' }, { id: 'B', text: 'Use AWS DataSync scheduled transfers to copy EFS data every 24 hours' }, { id: 'C', text: 'Create EFS snapshots and copy them cross-region daily via AWS Backup' }, { id: 'D', text: 'EFS automatically replicates data across all regions globally when enabled' }], correct: ['A'], explanation: 'EFS Replication provides continuous, automatic replication to an EFS file system in another region. RPO is typically under a minute. On failover, the replica is promoted to a standalone writable file system.', distractors: {
      D: 'EFS is regional — cross-region replication requires explicit EFS Replication configuration, not automatic.',
      B: 'DataSync daily copies have up to 24-hour RPO — not near-zero.',
      C: 'AWS Backup creates point-in-time snapshots — not continuous replication with near-zero RPO.'
    } },
  { id: 'd2-dr-042', domain: 2, topics: ['DR', 'Neptune Global Database'], type: 'single', stem: 'A company uses Amazon Neptune in us-east-1 and needs DR in eu-west-1 with fast cross-region replication and managed failover. What Neptune feature supports this?', options: [{ id: 'A', text: 'AWS DMS continuous replication for Neptune' }, { id: 'B', text: 'Neptune Global Database' }, { id: 'C', text: 'Neptune does not support cross-region DR' }, { id: 'D', text: 'Neptune daily snapshot copy to eu-west-1' }], correct: ['B'], explanation: 'Neptune Global Database (similar to Aurora Global Database) provides storage-level cross-region replication with <1 second typical lag. Secondary regions serve read traffic and can be promoted to primary on failover with fast RTO.', distractors: {
      C: 'Neptune Global Database specifically provides cross-region DR capability.',
      A: 'DMS replicates between databases but Neptune Global Database is the native, simpler solution for Neptune DR.',
      D: 'Daily snapshots provide point-in-time recovery — not continuous replication with sub-second RPO.'
    } },
  { id: 'd2-dr-043', domain: 2, topics: ['DR', 'active-active challenge', 'data consistency'], type: 'single', stem: 'A company is evaluating multi-region Active-Active architecture. What is the most significant technical CHALLENGE of this approach?', options: [{ id: 'A', text: 'Distributed write consistency and conflict resolution' }, { id: 'B', text: 'Higher infrastructure costs compared to single-region deployments' }, { id: 'C', text: 'Performance is worse because cross-region latency affects all user requests' }, { id: 'D', text: 'AWS does not support multi-region services for Active-Active patterns' }], correct: ['A'], explanation: 'Multi-region Active-Active\'s fundamental challenge: if both regions accept writes simultaneously, conflicts occur. Solutions (last-writer-wins, CRDTs, event sourcing, partition by geography) add significant application and operational complexity.', distractors: {
      B: 'Higher costs are real but manageable — distributed consistency is the fundamental engineering challenge that may be unsurmountable for some data models.',
      D: 'AWS explicitly supports and provides guidance for multi-region Active-Active patterns.',
      C: 'Performance for users near the second region actually improves — global latency decreases rather than increases.'
    } },
  { id: 'd2-dr-044', domain: 2, topics: ['DR', 'failover order of operations'], type: 'single', stem: 'During DR failover, what is the CORRECT order of operations to avoid data corruption and failed traffic routing?', options: [{ id: 'A', text: '1. Update DNS to DR → 2. Scale up DR resources → 3. Promote database replica' }, { id: 'B', text: '1. Update DNS immediately → 2. Hope DR resources provision in time' }, { id: 'C', text: '1. Terminate primary region → 2. Restore from the latest backup → 3. Update DNS after backup restore completes' }, { id: 'D', text: '1. Verify DR readiness → 2. Promote database replica → 3. Scale up application tier → 4. Update DNS to DR region' }], correct: ['D'], explanation: 'Safe failover: verify readiness, promote DB (enables writes), scale application (handles traffic volume), then update DNS last (directs traffic only when the DR environment is fully ready). This order minimizes user impact and risk.', distractors: {
      A: 'Updating DNS before DB promotion routes users to an application that cannot process writes — order matters significantly.',
      B: 'Updating DNS without readiness verification risks sending production traffic to a broken environment with no rollback.',
      C: 'Terminating primary prevents rollback to primary if DR fails — and backup restore has high RTO.'
    } },
  { id: 'd2-dr-045', domain: 2, topics: ['DR', 'Parameter Store', 'cross-region config'], type: 'single', stem: 'An application reads configuration from Systems Manager Parameter Store. During DR failover, the app fails because parameters don\'t exist in the secondary region. What should have been configured?', options: [{ id: 'A', text: 'Replicate Parameter Store parameters to the secondary region using automation (EventBridge + Lambda or AWS Backup)' }, { id: 'B', text: 'Hardcode all configuration values in the application code for DR scenarios' }, { id: 'C', text: 'Use cross-region IAM roles to access the primary region\'s Parameter Store from the DR region' }, { id: 'D', text: 'Parameter Store parameters are global and automatically available in all regions' }], correct: ['A'], explanation: 'Parameter Store is regional. DR preparation must include replicating all parameters to the secondary region. Use EventBridge + Lambda to sync parameters on change, or schedule regular replication to keep the DR region current.', distractors: {
      D: 'Parameter Store is regional — not automatically global. Parameters must be explicitly created or replicated in each region.',
      B: 'Hardcoding configuration defeats the purpose of Parameter Store and creates ongoing maintenance debt.',
      C: 'Cross-region Parameter Store access creates a dependency on the primary region — if it fails, the DR region also fails to read config.'
    } },
]
